<div class="table-wrap"><table class="data-table"><thead><tr><th>Bucket name</th><th>Objects</th><th>Storage used</th>@unless ($compact)<th>Quota</th>@endunless<th><span class="sr-only">Actions</span></th></tr></thead><tbody>
@forelse ($rows as $bucket)
    <tr><td><a class="table-name" href="{{ url('/buckets/'.$bucket->name) }}"><span class="name-icon"><x-console-icon name="bucket" /></span><span>{{ $bucket->name }}<small>{{ $bucket->created_at->format('M j, Y') }}</small></span></a></td><td class="text-muted">{{ number_format($bucket->active_objects_count) }}</td><td><x-byte-size :bytes="$bucket->active_bytes ?? 0" /></td>@unless ($compact)<td class="quota-cell">@if ($bucket->quota_bytes)<span class="quota-label"><x-byte-size :bytes="$bucket->quota_bytes" /><span>{{ number_format(min(100, ($bucket->active_bytes ?? 0) / $bucket->quota_bytes * 100), 0) }}%</span></span><meter class="quota-meter" min="0" max="{{ $bucket->quota_bytes }}" value="{{ $bucket->active_bytes ?? 0 }}" aria-label="Storage usage for {{ $bucket->name }}"></meter>@else<span class="badge badge-neutral">No limit</span>@endif</td>@endunless<td><div class="row-actions"><a class="text-link" href="{{ url('/buckets/'.$bucket->name) }}">Browse<x-console-icon name="chevron-right" /></a>@unless ($compact)<button class="icon-button" type="button" data-open-dialog="quota-{{ $bucket->id }}" aria-label="Edit quota for {{ $bucket->name }}"><x-console-icon name="settings" /></button>@if ($bucket->objects_count === 0 && $bucket->multipart_uploads_count === 0)<button class="icon-button" type="button" data-open-dialog="delete-bucket-{{ $bucket->id }}" aria-label="Delete {{ $bucket->name }}"><x-console-icon name="trash" /></button>@endif @endunless</div></td></tr>
@empty
    <tr><td colspan="{{ $compact ? 4 : 5 }}"><div class="empty-state"><div class="empty-icon"><x-console-icon name="bucket" /></div><h3>{{ $bucketRows->isEmpty() ? 'A home for your first object.' : 'No buckets match this name.' }}</h3><p>{{ $bucketRows->isEmpty() ? 'Create a bucket to keep application files organized and ready to use.' : 'Try another name or clear the bucket filter.' }}</p>@if ($bucketRows->isEmpty())<button class="btn btn-primary" type="button" data-open-dialog="create-bucket"><x-console-icon name="plus" />Create your first bucket</button>@endif</div></td></tr>
@endforelse
</tbody></table></div>
